import { useState, useEffect } from "react";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend, LineChart, Line } from "recharts";
import { getMonthlySummary, getTrends, getCategoryTrends, getBudgetStatus, createTransaction, getTransactions } from "../services/api";
import { G } from "../App";

const CATEGORIES = ["Food","Transport","Shopping","Health","Entertainment","Utilities","Education","Other"];
const CAT_COLORS = ["#2563eb","#7c3aed","#dc2626","#16a34a","#d97706","#0891b2","#9333ea","#64748b"];
const fmt = n => `₹${Number(n || 0).toLocaleString("en-IN")}`;
const now = new Date();

function StatCard({ label, value, sub, color, icon, bg }) {
  return (
    <div style={{ background: bg || "#fff", border: `1.5px solid ${color}30`, borderRadius: 16, padding: "22px 24px", position: "relative", overflow: "hidden", boxShadow: `0 4px 20px ${color}10` }}>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 4, background: color, borderRadius: "16px 16px 0 0" }} />
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
        <div>
          <div style={{ color: "#64748b", fontSize: 12, letterSpacing: 1, textTransform: "uppercase", fontWeight: 700, marginBottom: 8 }}>{label}</div>
          <div style={{ fontSize: 26, fontWeight: 900, color: "#0f172a", fontFamily: G.mono, letterSpacing: "-1px" }}>{value}</div>
          {sub && <div style={{ color: "#64748b", fontSize: 12, marginTop: 6 }}>{sub}</div>}
        </div>
        <div style={{ fontSize: 32, opacity: 0.8 }}>{icon}</div>
      </div>
    </div>
  );
}

export default function Dashboard({ user }) {
  const [summary, setSummary] = useState(null);
  const [trends, setTrends]   = useState([]);
  const [catData, setCatData] = useState([]);
  const [recent, setRecent]   = useState([]);
  const [form, setForm]       = useState({ description: "", amount: "", category: "Food", type: "expense", date: now.toISOString().split("T")[0] });
  const [saving, setSaving]   = useState(false);
  const [msg, setMsg]         = useState("");
  const month = now.getMonth() + 1;
  const year  = now.getFullYear();

  const load = () => {
    getMonthlySummary({ month, year }).then(r => setSummary(r.data)).catch(() => {});
    getTrends({ months: 6 }).then(r => setTrends(r.data.trends || [])).catch(() => {});
    getCategoryTrends({ month, year }).then(r => setCatData(r.data.categories || [])).catch(() => {});
    getTransactions({ month, year }).then(r => setRecent((r.data || []).slice(0, 8))).catch(() => {});
  };

  useEffect(() => { load(); }, []);

  const addTxn = async () => {
    if (!form.description || !form.amount) { setMsg("❌ Fill in description and amount."); return; }
    setSaving(true);
    try {
      await createTransaction({ ...form, amount: parseFloat(form.amount), date: new Date(form.date).toISOString() });
      setMsg("✅ Transaction added!"); setForm(f => ({ ...f, description: "", amount: "" }));
      load(); setTimeout(() => setMsg(""), 3000);
    } catch (e) { setMsg("❌ " + (e.response?.data?.detail || "Error")); }
    setSaving(false);
  };

  const income  = summary?.total_income  || 0;
  const expense = summary?.total_expense || 0;
  const balance = income - expense;

  const s = {
    page: { animation: "fadeIn 0.3s ease" },
    heading: { fontSize: 26, fontWeight: 900, color: "#0f172a", letterSpacing: "-0.5px", marginBottom: 4 },
    sub: { color: "#64748b", fontSize: 14, marginBottom: 28 },
    grid3: { display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 16, marginBottom: 24 },
    grid2: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20, marginBottom: 24 },
    card: { background: "#fff", border: "1.5px solid #dbeafe", borderRadius: 16, padding: 24, boxShadow: "0 2px 12px rgba(37,99,235,0.06)" },
    cardTitle: { fontSize: 14, fontWeight: 800, color: "#1e3a8a", letterSpacing: 0.3, marginBottom: 18, display: "flex", alignItems: "center", gap: 8 },
    input: { background: "#f8faff", border: "1.5px solid #dbeafe", borderRadius: 10, padding: "10px 14px", color: "#0f172a", fontSize: 13, fontFamily: G.font, width: "100%" },
    select: { background: "#f8faff", border: "1.5px solid #dbeafe", borderRadius: 10, padding: "10px 14px", color: "#0f172a", fontSize: 13, fontFamily: G.font, width: "100%" },
    row2: { display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 12 },
    row3: { display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12, marginBottom: 12 },
    label: { fontSize: 11, color: "#64748b", fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", marginBottom: 5, display: "block" },
    btn: { padding: "11px 20px", background: "linear-gradient(135deg, #2563eb, #1d4ed8)", border: "none", borderRadius: 10, color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: G.font, boxShadow: "0 4px 14px rgba(37,99,235,0.3)" },
    incomeBtn: { padding: "8px 18px", background: "#f0fdf4", border: "2px solid #16a34a", borderRadius: 8, color: "#16a34a", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: G.font },
    expenseBtn: { padding: "8px 18px", background: "#fef2f2", border: "2px solid #dc2626", borderRadius: 8, color: "#dc2626", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: G.font },
    activeIncome: { padding: "8px 18px", background: "#16a34a", border: "2px solid #16a34a", borderRadius: 8, color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: G.font },
    activeExpense: { padding: "8px 18px", background: "#dc2626", border: "2px solid #dc2626", borderRadius: 8, color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: G.font },
    msg: (ok) => ({ background: ok ? "#f0fdf4" : "#fef2f2", border: `1px solid ${ok ? "#bbf7d0" : "#fecaca"}`, borderRadius: 8, padding: "10px 14px", fontSize: 13, color: ok ? "#16a34a" : "#dc2626", marginBottom: 12 }),
    txnRow: { display: "flex", justifyContent: "space-between", alignItems: "center", padding: "12px 0", borderBottom: "1px solid #f1f5f9" },
    badge: (t) => ({ background: t === "income" ? "#f0fdf4" : "#fef2f2", color: t === "income" ? "#16a34a" : "#dc2626", border: `1px solid ${t === "income" ? "#bbf7d0" : "#fecaca"}`, padding: "3px 10px", borderRadius: 20, fontSize: 11, fontWeight: 700 }),
  };

  const trendChartData = trends.map(t => ({ name: `${t.month}/${t.year}`, Income: t.total_income, Expense: t.total_expense }));
  const pieData = catData.filter(c => c.total > 0).map((c, i) => ({ name: c.category, value: Math.round(c.total), color: CAT_COLORS[i % CAT_COLORS.length] }));

  return (
    <div style={s.page}>
      <div style={s.heading}>Welcome back, {user?.name?.split(" ")[0]} 👋</div>
      <div style={s.sub}>{new Date().toLocaleDateString("en-IN", { weekday: "long", year: "numeric", month: "long", day: "numeric" })}</div>

      {/* Summary Cards */}
      <div style={s.grid3}>
        <StatCard label="Total Income" value={fmt(income)} sub="This month" color="#16a34a" icon="💰" />
        <StatCard label="Total Expenses" value={fmt(expense)} sub="This month" color="#dc2626" icon="💸" />
        <StatCard label="Balance" value={fmt(balance)} sub={balance >= 0 ? "You're in profit!" : "Overspent"} color={balance >= 0 ? "#2563eb" : "#dc2626"} icon="🏦" />
      </div>

      <div style={s.grid2}>
        {/* Quick Add Transaction */}
        <div style={s.card}>
          <div style={s.cardTitle}>➕ Quick Add Transaction</div>
          {msg && <div style={s.msg(msg.startsWith("✅"))}>{msg}</div>}

          {/* Type Toggle */}
          <div style={{ display: "flex", gap: 10, marginBottom: 14 }}>
            <button style={form.type === "expense" ? s.activeExpense : s.expenseBtn} onClick={() => setForm(f => ({ ...f, type: "expense", category: "Food" }))}>💸 Expense</button>
            <button style={form.type === "income" ? s.activeIncome : s.incomeBtn} onClick={() => setForm(f => ({ ...f, type: "income", category: "Other" }))}>💰 Income</button>
          </div>

          <div style={s.row2}>
            <div>
              <label style={s.label}>Description</label>
              <input style={s.input} placeholder="e.g. Lunch, Salary..." value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} onKeyDown={e => e.key === "Enter" && addTxn()} />
            </div>
            <div>
              <label style={s.label}>Amount (₹)</label>
              <input style={s.input} type="number" placeholder="0.00" value={form.amount} onChange={e => setForm(f => ({ ...f, amount: e.target.value }))} onKeyDown={e => e.key === "Enter" && addTxn()} />
            </div>
          </div>
          <div style={s.row2}>
            <div>
              <label style={s.label}>Category</label>
              <select style={s.select} value={form.category} onChange={e => setForm(f => ({ ...f, category: e.target.value }))}>
                {(form.type === "income" ? ["Salary","Freelance","Business","Investment","Other"] : CATEGORIES).map(c => <option key={c}>{c}</option>)}
              </select>
            </div>
            <div>
              <label style={s.label}>Date</label>
              <input style={s.input} type="date" value={form.date} onChange={e => setForm(f => ({ ...f, date: e.target.value }))} />
            </div>
          </div>
          <button style={s.btn} onClick={addTxn} disabled={saving}>{saving ? "Adding..." : `Add ${form.type === "income" ? "Income" : "Expense"}`}</button>
        </div>

        {/* Recent Transactions */}
        <div style={s.card}>
          <div style={s.cardTitle}>🕐 Recent Transactions</div>
          {recent.length === 0 ? (
            <div style={{ color: "#94a3b8", fontSize: 13, textAlign: "center", padding: "30px 0" }}>No transactions yet. Add one!</div>
          ) : recent.map(t => (
            <div key={t.id} style={s.txnRow}>
              <div>
                <div style={{ fontWeight: 600, fontSize: 13, color: "#0f172a" }}>{t.description}</div>
                <div style={{ fontSize: 11, color: "#94a3b8", marginTop: 2 }}>{t.category} • {new Date(t.date).toLocaleDateString("en-IN")}</div>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ fontFamily: G.mono, fontWeight: 800, fontSize: 14, color: t.type === "income" ? "#16a34a" : "#dc2626" }}>
                  {t.type === "income" ? "+" : "-"}{fmt(t.amount)}
                </span>
                <span style={s.badge(t.type)}>{t.type}</span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Charts */}
      <div style={s.grid2}>
        {/* Income vs Expense Bar Chart */}
        <div style={s.card}>
          <div style={s.cardTitle}>📊 Income vs Expense (6 Months)</div>
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={trendChartData} barGap={4}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
              <XAxis dataKey="name" tick={{ fontSize: 11, fill: "#94a3b8" }} />
              <YAxis tick={{ fontSize: 11, fill: "#94a3b8" }} tickFormatter={v => `₹${v/1000}k`} />
              <Tooltip formatter={v => fmt(v)} contentStyle={{ background: "#fff", border: "1px solid #dbeafe", borderRadius: 8, fontSize: 12 }} />
              <Legend />
              <Bar dataKey="Income" fill="#16a34a" radius={[4,4,0,0]} />
              <Bar dataKey="Expense" fill="#dc2626" radius={[4,4,0,0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>

        {/* Category Pie Chart */}
        <div style={s.card}>
          <div style={s.cardTitle}>🥧 Category-wise Expenses</div>
          {pieData.length === 0 ? (
            <div style={{ color: "#94a3b8", fontSize: 13, textAlign: "center", padding: "60px 0" }}>Add expenses to see breakdown</div>
          ) : (
            <ResponsiveContainer width="100%" height={220}>
              <PieChart>
                <Pie data={pieData} cx="50%" cy="50%" innerRadius={55} outerRadius={90} dataKey="value" paddingAngle={3}>
                  {pieData.map((entry, i) => <Cell key={i} fill={entry.color} />)}
                </Pie>
                <Tooltip formatter={v => fmt(v)} contentStyle={{ background: "#fff", border: "1px solid #dbeafe", borderRadius: 8, fontSize: 12 }} />
                <Legend iconType="circle" iconSize={8} />
              </PieChart>
            </ResponsiveContainer>
          )}
        </div>
      </div>
    </div>
  );
}
